return items.map(item => ({
  json: {
    to: item.json.email || 'sin-correo@demo.local',
    subject: 'SION UNAC - Pago confirmado',
    name: item.json.name || 'Aspirante',
    program: item.json.program,
    amount: item.json.amount,
    method: item.json.method,
    transactionId: item.json.transactionId || 'N/A',
    body: 'Hola ' + (item.json.name || 'Aspirante') + ', confirmamos tu pago de $' + item.json.amount + ' COP por inscripcion a ' + item.json.program + '.',
    sentAt: new Date().toISOString()
  }
}));
